const char *vertrix_import_name(uint32_t address)
{
    size_t low = 0, high = sizeof imports / sizeof imports[0];
    while (low < high)
    {
        size_t mid = (low + high) / 2;
        if (imports[mid].slot == address)
        {
            return imports[mid].name;
        }
        if (imports[mid].slot < address)
        {
            low = mid + 1;
        }
        else
        {
            high = mid;
        }
    }
    return NULL;
}

uint32_t vertrix_import_slot(const uint8_t *image, uint32_t base, uint32_t address)
{
    const uint8_t *code;
    if (address < base + 0xf0000u || address >= base + 0xf1000u)
    {
        return address;
    }
    code = image + (address - base);
    if (code[0] == 0xff && code[1] == 0x25)
    {
        return (uint32_t)code[2] | (uint32_t)code[3] << 8 | (uint32_t)code[4] << 16 |
               (uint32_t)code[5] << 24;
    }
    return address;
}
